          if (r > g.R + 1) { d[i + 3] = 0; continue; }
          const hue = ((Math.atan2(dx, -dy) * 180) / Math.PI + 360) % 360;   // 顶部为 0°，顺时针
          const [R, G, B] = hexRgb(hsvHex(hue, Math.min(1, r / g.R), 1));
