      const a = this._popAnchor.getBoundingClientRect(), rr = this.root.getBoundingClientRect(), bar = this.picker.getBoundingClientRect();
      const ax = a.left - rr.left, ay = a.top - rr.top, aw = a.width, ah = a.height;
      const gap = 16;
