      const availW = this.dock === 'bottom' ? this.W - 16 : (this.dock === 'left' ? this.W - (bar.right - rr.left) - gap - 8 : bar.left - rr.left - gap - 8);
      const sc = Math.min(1, availH / ph, availW / pw);
